"""Module 10 concepts: servomechanisms, synchros and servomotor control (EASA M04 SM03; SERVOMECHANISM sv)."""
from lib import K
M = 'm10'
K('m10-servo-loop', M, ('Hệ servo, vòng hở/kín và bộ sai số', 'The servo, open/closed loop and the follow-up'),
  ('Servo là hệ điều khiển điện dùng tín hiệu năng lượng thấp để tạo chuyển động hoặc lực lớn. Vòng kín so ngõ ra với ngõ vào và kéo sai số về 0 (null); bộ sai số (follow-up) tính “mong muốn trừ thực tế”.', 'A servo is an electric control system that uses a low-energy input to produce motion or force. A closed loop compares the output with the input and drives the error to zero (null); the follow-up computes “desired minus actual”.'),
  facts=[('sai số = vị trí mong muốn − vị trí thực', ('Servomotor dừng khi điện áp ở điểm cộng bằng 0.', 'The servomotor stops when the summing-point voltage is zero.'))],
  steps=[('Chuỗi vòng: mạng cộng điện trở → bộ khuếch đại → servomotor → hộp số → tải → cảm biến phản hồi.', 'The loop chain: resistor summing network → amplifier → servomotor → gear train → load → feedback transducer.')],
  traps=[('Cho rằng vòng hở có phản hồi: vòng hở không so ngõ ra với ngõ vào.', 'Thinking an open loop has feedback: it never compares output with input.')],
  angles=[('Sự khác nhau giữa vòng hở và vòng kín.', 'The difference between open and closed loop.'), ('Điểm cộng bằng 0 nghĩa là gì?', 'What does a zero summing point mean?')],
  topics=['Open/closed loop and the follow-up', 'Servo loops and components'], kw=['servo', 'servomechanism', 'closed loop', 'open loop', 'follow-up', 'error', 'null', 'summing point', 'feedback', 'autopilot', 'afcs'], kwv=['servo', 'hệ servo', 'vòng kín', 'vòng hở', 'sai số', 'điểm cộng', 'phản hồi', 'lái tự động'],
  src=['EASA M04 SM03 pp.3.2–3.4', 'SERVOMECHANISM pp.66–68'], related=['m04-feedback', 'm10-stability'], chk='servoloop')
K('m10-lvdt', M, ('Cảm biến vị trí LVDT và RVDT', 'LVDT and RVDT position transducers'),
  ('LVDT có một cuộn sơ cấp, hai cuộn thứ cấp và lõi di động; hiệu hai điện áp thứ cấp là tín hiệu phản hồi. Lõi ở giữa cho hai điện áp bằng nhau, ngược pha → ngõ ra 0 (null); RVDT đo góc.', 'The LVDT has one primary, two secondaries and a moving core; the difference of the secondary voltages is the feedback signal. A centred core gives equal, opposite voltages → zero output (null); the RVDT measures angle.'),
  facts=[('V_ra = V_S1 − V_S2', ('Biên độ ∝ độ dời, pha cho biết chiều.', 'The amplitude ∝ displacement, the phase gives the direction.'))],
  steps=[('Lõi lệch về một phía → một thứ cấp lớn hơn → ngõ ra khác 0 với pha tương ứng chiều lệch.', 'Core off-centre → one secondary larger → non-zero output with a phase matching the direction.')],
  traps=[('Nghĩ LVDT có tiếp xúc cơ học: chỉ có liên kết cảm ứng nên bền và ổn định.', 'Thinking the LVDT has mechanical contact: it only has an inductive link, so it is durable and stable.')],
  angles=[('Ngõ ra LVDT khi lõi ở giữa?', 'LVDT output with the core centred?'), ('RVDT khác LVDT thế nào?', 'How does the RVDT differ from the LVDT?')],
  topics=['Transducers: LVDT, RVDT, inductive, capacitive'], kw=['lvdt', 'rvdt', 'linear variable differential transformer', 'moving core', 'displacement', 'position transducer', 'inductance transmitter', 'capacitance transmitter'], kwv=['lvdt', 'rvdt', 'lõi di động', 'độ dời', 'cảm biến vị trí', 'điện dung'],
  src=['EASA M04 SM03 p.3.4, 3.10'], related=['m10-servo-loop'], chk='lvdt')
K('m10-synchro', M, ('Synchro: máy phát, máy thu và điện áp stator', 'Synchros: transmitter, receiver and stator voltages'),
  ('Synchro là biến áp biến đổi: một sơ cấp (rôto) quay 360° và ba thứ cấp (stato) cách nhau 120°. Điện áp mỗi cuộn stato phụ thuộc góc rôto; hai synchro nối với nhau truyền góc từ xa. Máy thu có bộ giảm chấn chống hunting; hai góc bằng nhau thì không có dòng.', 'A synchro is a variable transformer: one primary (rotor) turning 360° and three secondaries (stator) spaced 120°. Each stator-coil voltage depends on the rotor angle; two linked synchros transmit an angle remotely. The receiver has a damper against hunting; at equal angles no current flows.'),
  facts=[('rôto 115 V, tỉ số giảm áp 2,2:1 → khoảng 52 V cực đại ở một cuộn stato', ('Ví dụ từ tài liệu servo.', 'Example from the servo notes.')), ('DC selsyn: cần gạt trên cuộn điện trở; autosyn: AC, nam châm điện; magnasyn: AC, nam châm vĩnh cửu', ('Ba kiểu synchro cổ điển.', 'Three classic synchro types.'))],
  steps=[('Điện áp cuộn stato = giá trị cực đại × hàm góc rôto; ba cuộn lệch 120° nên ba điện áp xác định duy nhất một góc.', 'Stator-coil voltage = peak × a function of rotor angle; the coils are 120° apart, so the three voltages identify one angle uniquely.'), ('Máy thu quay theo từ trường như thanh nam châm trong từ trường.', 'The receiver follows the field like a bar magnet in a magnetic field.')],
  traps=[('Nhầm magnasyn (nam châm vĩnh cửu) với autosyn (nam châm điện).', 'Confusing magnasyn (permanent magnet) with autosyn (electromagnet).'), ('Nhầm 120° của synchro với 90° của resolver.', 'Confusing the synchro 120° with the resolver 90°.')],
  angles=[('Ba cuộn stato lệch nhau bao nhiêu độ?', 'How far apart are the three stator coils?'), ('Rôto 115 V, tỉ số 2,2:1: điện áp stato cực đại?', 'Rotor 115 V with a 2.2:1 ratio: peak stator voltage?')],
  topics=['Synchro systems'], kw=['synchro', 'torque synchro', 'rotor', 'stator', '120', 'transmitter', 'receiver', 'selsyn', 'autosyn', 'magnasyn', 'damper', 'remote indication'], kwv=['synchro', 'rôto', 'stato', 'cuộn stato', 'máy phát', 'máy thu', 'selsyn', 'autosyn', 'magnasyn', 'giảm chấn'],
  src=['EASA M04 SM03 pp.3.4–3.10', 'SERVOMECHANISM pp.1–2, 14'], related=['m10-control-synchro', 'm10-resolver'], chk='synchro')
K('m10-control-synchro', M, ('Synchro điều khiển (CX–CT) và synchro vi sai', 'Control synchros (CX–CT) and differential synchros'),
  ('Máy phát điều khiển CX nối với biến áp điều khiển CT; rôto CT cho điện áp sai số tỉ lệ với hiệu góc: cùng pha với nguồn cho một chiều lệch, ngược pha 180° cho chiều kia, bằng 0 ở điểm khớp. Tín hiệu được khuếch đại để servomotor quay tải về null. TDX nhận hai góc và cho tổng hoặc hiệu (đảo S1–S3 để biến cộng thành trừ).', 'The control transmitter CX feeds the control transformer CT; the CT rotor gives an error voltage proportional to the angular difference: in phase with the supply for one direction of error, 180° out of phase for the other, zero at correspondence. The error is amplified so the servomotor turns the load back to null. The TDX takes two angles and gives their sum or difference (reverse S1–S3 to turn adding into subtracting).'),
  facts=[('V_lỗi ∝ sin(θ lệch) ≈ θ lệch với góc nhỏ', ('Chiều lệch cho bởi pha của V_lỗi.', 'The direction of error is given by the phase of V_error.'))],
  steps=[('Đọc pha của điện áp sai số để biết chiều quay; đọc biên độ để biết độ lớn.', 'Read the phase of the error voltage for the direction, its amplitude for the size.')],
  traps=[('Cho rằng CT cho điện áp lớn nhất khi hai góc khớp: nó bằng 0 tại điểm khớp.', 'Thinking the CT gives its maximum when the angles match: it is zero at correspondence.')],
  angles=[('Điện áp CT tại điểm khớp?', 'CT output at correspondence?'), ('Làm sao biến synchro vi sai từ cộng thành trừ?', 'How do you turn a differential synchro from adding to subtracting?')],
  topics=['Differential, control synchros and resolvers'], kw=['control synchro', 'cx', 'ct', 'control transformer', 'control transmitter', 'error voltage', 'differential synchro', 'tdx', 'tdr', 'phase', 'correspondence'], kwv=['synchro điều khiển', 'biến áp điều khiển', 'điện áp sai số', 'synchro vi sai', 'khớp góc', 'pha'],
  src=['EASA M04 SM03 pp.3.7–3.10', 'SERVOMECHANISM pp.34–36'], related=['m10-synchro', 'm10-servo-loop'], chk='controlsynchro')
K('m10-resolver', M, ('Resolver', 'The resolver'),
  ('Resolver có hai cuộn stato lệch 90° cho sin θ và cos θ; đưa vào bộ chuyển đổi A/D cho máy tính bay. Đây là thiết bị đo góc bền nhất.', 'The resolver has two stator windings 90° apart giving sin θ and cos θ; fed to an ADC for the flight computers. It is the most robust angular-measurement device.'),
  facts=[('V_S1 ∝ sin θ ,  V_S2 ∝ cos θ', ('Hai cuộn lệch 90°.', 'Two windings 90° apart.'))],
  steps=[('Góc θ = atan2(V_sin, V_cos).', 'Angle θ = atan2(V_sin, V_cos).')],
  traps=[('Nhầm 90° (resolver) với 120° (synchro).', 'Confusing 90° (resolver) with 120° (synchro).')],
  angles=[('Resolver có bao nhiêu cuộn stato và lệch bao nhiêu độ?', 'How many stator windings does a resolver have and how far apart?')],
  topics=['Differential, control synchros and resolvers'], kw=['resolver', 'sin', 'cos', 'sine', 'cosine', '90', 'angle measurement'], kwv=['resolver', 'sin', 'cos', 'đo góc', '90°'],
  src=['EASA M04 SM03 p.3.9'], related=['m10-synchro', 'm05-adc-dac'], chk='resolver')
K('m10-stability', M, ('Ổn định, hunting, tắt dần và vùng chết', 'Stability, hunting, damping and deadband'),
  ('Quán tính đẩy servomotor vượt qua điểm null, sai số đổi pha và quá trình lặp lại: đó là hunting. Chống bằng tắt dần: phản hồi vận tốc (máy phát tốc) hoặc giảm chấn nhớt (cốc kéo + bánh đà nam châm). Quá tắt dần thì chậm, thiếu tắt dần thì dao động; độ lợi cao giảm trễ nhưng tăng vọt lố. Vùng chết hẹp cho độ chính xác cao nhưng dễ hunting.', 'Inertia carries the motor past the null, the error reverses phase and the process repeats: this is hunting. Cure it with damping: velocity feedback (a tachogenerator) or a viscous damper (drag cup + magnet flywheel). Overdamped is slow, underdamped oscillates; more gain cuts lag but increases overshoot. A narrow deadband gives high precision but invites hunting.'),
  facts=[('vận tốc ổn định khi sai số vừa đủ để động cơ quay đúng tốc độ máy phát tốc báo', ('Ví dụ: động cơ 10 rpm/V, máy phát tốc 1 V/10 rpm.', 'Example: motor 10 rpm/V, tach 1 V/10 rpm.'))],
  steps=[('Điểm cộng = trung bình các điện áp khi R2 = R3.', 'The summing point = average of the voltages when R2 = R3.'), ('Cân bằng: sai số × hệ số động cơ = tốc độ = tốc độ máy phát tốc.', 'Balance: error × motor constant = speed = speed reported by the tachometer.')],
  traps=[('Tăng độ lợi để chính xác hơn mà quên hunting.', 'Raising the gain for accuracy and forgetting hunting.'), ('Đảo dây phản hồi: hệ mất ổn định.', 'Reversing the feedback leads can make the system unstable.')],
  angles=[('Hunting là gì và chống bằng cách nào?', 'What is hunting and how is it prevented?'), ('Tốc độ cân bằng của servo vận tốc với điều khiển −9 V.', 'Steady speed of a velocity servo with a −9 V control.')],
  topics=['Stability, hunting and damping'], kw=['hunting', 'damping', 'overshoot', 'deadband', 'stability', 'tachometer', 'tachogenerator', 'velocity feedback', 'overdamped', 'underdamped', 'time lag', 'oscillat'], kwv=['hunting', 'tắt dần', 'vọt lố', 'vùng chết', 'ổn định', 'máy phát tốc', 'phản hồi vận tốc', 'trễ thời gian'],
  src=['EASA M04 SM03 pp.3.10–3.12', 'SERVOMECHANISM pp.66–77'], related=['m10-servo-loop', 'm04-feedback'], chk='stability')
K('m10-pwm', M, ('Điều khiển servomotor bằng PWM', 'Servomotor control by pulse-width modulation'),
  ('PWM đổi điện áp trung bình đặt lên động cơ bằng chu kỳ làm việc của xung. 555 phi ổn tạo xung với duty điều chỉnh được (module 07); Floyd không có mạch 555 lái servo, đây là ứng dụng ghép từ các nguyên lý.', 'PWM changes the average voltage on the motor through the duty cycle of the pulses. An astable 555 makes pulses with an adjustable duty cycle (module 07); Floyd has no 555 circuit that drives a servo, so this is an application assembled from the principles.'),
  facts=[('V_tb = duty × V_cao', ('duty = t_H/T.', 'duty = t_H/T.'))],
  steps=[('Tính duty từ R1, R2 của 555, rồi điện áp trung bình.', 'Compute the duty from R1, R2 of the 555, then the average voltage.')],
  traps=[('Cho rằng PWM đổi biên độ xung: nó đổi độ rộng.', 'Thinking PWM changes the pulse amplitude: it changes the width.')],
  angles=[('Duty 40 %, xung 12 V: điện áp trung bình?', 'Duty 40 %, 12 V pulses: average voltage?')],
  topics=['Servo loops and components'], kw=['pwm', 'pulse width modulation', 'duty cycle', 'servomotor', 'motor drive', 'average voltage'], kwv=['pwm', 'điều chế độ rộng xung', 'chu kỳ làm việc', 'điều khiển động cơ', 'điện áp trung bình'],
  src=['Floyd 9e §9–4', 'Floyd 9e §16–6'], related=['m07-555-astable', 'm10-servo-loop'], chk='pwm')
